require_once '../includes/privacy_lifecycle.php';
$policies = $pdo->query('SELECT * FROM privacy_retention_policies ORDER BY PolicyID')->fetchAll(PDO::FETCH_ASSOC);
$requests = $pdo->query("SELECT pr.*,u.FirstName,u.LastName,u.Email,r.FirstName ReviewerFirst,r.LastName ReviewerLast FROM privacy_requests pr JOIN users u ON u.UserID=pr.UserID LEFT JOIN users r ON r.UserID=pr.ReviewedBy ORDER BY FIELD(pr.Status,'Submitted','Under Review','Approved','Partially Approved','Denied','Completed'),pr.DueAt")->fetchAll(PDO::FETCH_ASSOC);
$cases = $pdo->query('SELECT c.*,p.RecordLabel,p.DisposalMethod,a.FirstName ApproverFirst,a.LastName ApproverLast FROM privacy_retention_cases c JOIN privacy_retention_policies p ON p.PolicyKey=c.PolicyKey LEFT JOIN users a ON a.UserID=c.ApprovedBy ORDER BY FIELD(c.Status,\'Eligible\',\'Approved\',\'Deferred\',\'Completed\',\'Cancelled\'),c.EligibleAt DESC LIMIT 250')->fetchAll(PDO::FETCH_ASSOC);
$counts = ['requests'=>(int)$pdo->query("SELECT COUNT(*) FROM privacy_requests WHERE Status IN('Submitted','Under Review')")->fetchColumn(),'eligible'=>(int)$pdo->query("SELECT COUNT(*) FROM privacy_retention_cases WHERE Status='Eligible' AND LegalHold=0")->fetchColumn(),'holds'=>(int)$pdo->query('SELECT COUNT(*) FROM privacy_retention_cases WHERE LegalHold=1')->fetchColumn()];
