<h2 class="text-xl font-black mt-10 mb-4">Retention policies</h2><div class="grid lg:grid-cols-2 gap-4"><?php foreach($policies as $p):?><form action="../actions/process_privacy_lifecycle.php" method="post" class="bg-white border rounded-2xl p-5 space-y-3"><input type="hidden" name="action" value="save_policy"><input type="hidden" name="policy_id" value="<?=pv($p['PolicyID'])?>"><div class="flex justify-between gap-4"><div><h3 class="font-black"><?=pv($p['RecordLabel'])?></h3><p class="text-xs text-slate-400 mt-1"><?=pv($p['PolicyKey'])?></p></div><span class="text-xs font-black text-blue-700"><?=pv($p['DisposalMethod'])?></span></div><div class="grid sm:grid-cols-2 gap-3"><label class="text-xs font-black uppercase text-slate-500">Retention days<input type="number" min="1" max="36500" name="retention_days" value="<?=pv($p['RetentionDays'])?>" required class="mt-1 w-full p-3 border rounded-xl"></label><label class="text-xs font-black uppercase text-slate-500">Disposition<select name="disposal_method" class="mt-1 w-full p-3 border rounded-xl"><?php foreach(['Anonymize','Secure Delete','Review Only'] as $m):?><option <?=$p['DisposalMethod']===$m?'selected':''?>><?=pv($m)?></option><?php endforeach;?></select></label></div><label class="block text-xs font-black uppercase text-slate-500">Trigger event<input name="trigger_event" minlength="5" value="<?=pv($p['TriggerEvent'])?>" required class="mt-1 w-full p-3 border rounded-xl"></label><label class="block text-xs font-black uppercase text-slate-500">Legal / operational basis<textarea name="legal_basis" minlength="10" required rows="2" class="mt-1 w-full p-3 border rounded-xl"><?=pv($p['LegalBasis'])?></textarea></label><button class="px-4 py-2 bg-blue-600 text-white rounded-xl text-xs font-black uppercase">Save Policy</button></form><?php endforeach;?></div>

<h2 class="text-xl font-black mt-10 mb-4">Privacy requests</h2><div class="space-y-4"><?php foreach($requests as $r):?><article class="bg-white border rounded-2xl p-5"><div class="flex flex-col lg:flex-row justify-between gap-4"><div><div class="flex gap-2 items-center flex-wrap"><b>#<?=pv($r['RequestID'])?> · <?=pv($r['RequestType'])?></b><span class="px-2 py-1 bg-blue-50 text-blue-700 rounded-lg text-[10px] font-black uppercase"><?=pv($r['Status'])?></span><?php if(strtotime($r['DueAt'])<time()&&!in_array($r['Status'],['Denied','Completed'],true)):?><span class="text-red-600 text-xs font-black">OVERDUE</span><?php endif;?></div><p class="text-sm text-slate-500 mt-1"><?=pv($r['FirstName'].' '.$r['LastName'])?> · <?=pv($r['Email'])?> · due <?=date('M j, Y',strtotime($r['DueAt']))?></p><p class="mt-3 text-sm"><?=nl2br(pv($r['RequestDetails']))?></p></div><a href="../actions/export_privacy_data.php?user_id=<?=pv($r['UserID'])?>" class="text-xs font-black text-blue-700 whitespace-nowrap">Export subject data →</a></div><form action="../actions/process_privacy_lifecycle.php" method="post" class="mt-4 grid lg:grid-cols-[180px_1fr_auto] gap-3"><input type="hidden" name="action" value="resolve_request"><input type="hidden" name="request_id" value="<?=pv($r['RequestID'])?>"><select name="status" class="p-3 border rounded-xl"><?php foreach(['Under Review','Approved','Partially Approved','Denied','Completed'] as $s):?><option <?=$r['Status']===$s?'selected':''?>><?=pv($s)?></option><?php endforeach;?></select><input name="resolution_notes" minlength="10" required value="<?=pv($r['ResolutionNotes'])?>" placeholder="Decision, limitations, legal basis, and action taken" class="p-3 border rounded-xl"><button class="px-4 py-3 bg-slate-900 text-white rounded-xl text-xs font-black uppercase">Record Decision</button></form></article><?php endforeach;?><?php if(!$requests):?><div class="p-8 bg-white border rounded-2xl text-center text-slate-500">No privacy requests.</div><?php endif;?></div>

<h2 class="text-xl font-black mt-10 mb-4">Retention review queue</h2><div class="space-y-4"><?php foreach($cases as $c):?><article class="bg-white border rounded-2xl p-5"><div class="flex flex-col lg:flex-row justify-between gap-3"><div><div class="flex gap-2 flex-wrap items-center"><b>#<?=pv($c['CaseID'])?> · <?=pv($c['RecordLabel'])?></b><span class="px-2 py-1 bg-slate-100 rounded-lg text-[10px] font-black uppercase"><?=pv($c['Status'])?></span><?php if($c['LegalHold']):?><span class="px-2 py-1 bg-red-50 text-red-700 rounded-lg text-[10px] font-black uppercase">Legal hold</span><?php endif;?></div><p class="text-sm mt-2"><?=pv($c['RecordDescription'])?></p><p class="text-xs text-slate-400 mt-1">Eligible <?=date('M j, Y g:i A',strtotime($c['EligibleAt']))?> · <?=pv($c['DisposalMethod'])?></p><?php if($c['DispositionEvidence']):?><p class="mt-2 text-xs text-green-700 font-bold">Evidence: <?=pv($c['DispositionEvidence'])?></p><?php endif;?></div></div>
<?php if(!in_array($c['Status'],['Completed','Cancelled'],true)):?><div class="grid lg:grid-cols-2 gap-3 mt-4"><form action="../actions/process_privacy_lifecycle.php" method="post" class="flex gap-2"><input type="hidden" name="action" value="case_hold"><input type="hidden" name="case_id" value="<?=pv($c['CaseID'])?>"><input type="hidden" name="legal_hold" value="<?=$c['LegalHold']?'0':'1'?>"><input name="reason" <?=$c['LegalHold']?'':'required minlength="10"'?> placeholder="<?=$c['LegalHold']?'Optional release note':'Investigation/appeal/legal-hold reason'?>" class="min-w-0 flex-1 p-3 border rounded-xl"><button class="px-3 py-2 <?=$c['LegalHold']?'bg-green-600':'bg-red-600'?> text-white rounded-xl text-xs font-black"><?=$c['LegalHold']?'Release Hold':'Place Hold'?></button></form><?php if($c['Status']==='Eligible'&&!$c['LegalHold']):?><form action="../actions/process_privacy_lifecycle.php" method="post" class="flex gap-2"><input type="hidden" name="action" value="approve_case"><input type="hidden" name="case_id" value="<?=pv($c['CaseID'])?>"><input name="reason" minlength="10" required placeholder="Approval basis and scope" class="min-w-0 flex-1 p-3 border rounded-xl"><button class="px-3 py-2 bg-amber-500 text-white rounded-xl text-xs font-black">Approve</button></form><?php elseif($c['Status']==='Approved'):?><form action="../actions/process_privacy_lifecycle.php" method="post" onsubmit="return confirm('Execute the approved disposition? This may permanently remove files or personal data.');" class="flex gap-2"><input type="hidden" name="action" value="execute_case"><input type="hidden" name="case_id" value="<?=pv($c['CaseID'])?>"><input name="confirmation" required pattern="DISPOSE" placeholder="Type DISPOSE" class="min-w-0 flex-1 p-3 border border-red-300 rounded-xl"><button class="px-3 py-2 bg-red-700 text-white rounded-xl text-xs font-black">Execute</button></form><?php endif;?></div><?php endif;?></article><?php endforeach;?><?php if(!$cases):?><div class="p-8 